define('taoQtiTest/controller/creator/helpers/rubricBlockAudience',['lodash'], function (_) {
  'use strict';

  var rubricBlockViewOptions = [{
    value: 'candidate',
    label: 'Candidate'
  }, {
    value: 'author',
    label: 'Author'
  }, {
    value: 'proctor',
    label: 'Proctor'
  }, {
    value: 'scorer',
    label: 'Scorer'
  }, {
    value: 'testConstructor',
    label: 'Test constructor'
  }, {
    value: 'tutor',
    label: 'Tutor'
  }];
  var options = rubricBlockViewOptions.slice();
  return {
    getOptions() {
      return options.slice();
    },
    getDefaultView() {
      return options[0].value;
    },
    getValidView(view, legacyViews) {
      var allowedValues = options.map(option => option.value);
      var legacyValue = _.isArray(legacyViews) && legacyViews.length > 0 ? legacyViews[0] : null;
      var candidateValue = typeof view === 'string' && view.length > 0 ? view : legacyValue;
      return _.includes(allowedValues, candidateValue) ? candidateValue : this.getDefaultView();
    }
  };
});
